from pandas import Timestamp
import plotly.graph_objects as go
import numpy as np

def visualize_pl_distribution(trade_list, bins=30):

    profits = []
    losses  = []

    for trade in trade_list:
        pnl = trade[1]
        if pnl > 0:
            profits.append(pnl)
        elif pnl < 0:
            losses.append(pnl)

    print(f"\n\nFound {len(trade_list)} trades on trade_list")
    print(f"Found {len(profits)} profitable trades")
    print(f"Found {len(losses)} losing trades")

    # --- Convert to numpy ---
    profits = np.array(profits)
    losses  = np.array(losses)

    # --- Histogram traces ---
    fig = go.Figure()

    if len(profits) > 0:
        fig.add_trace(go.Histogram(
            x=profits,
            nbinsx=bins,
            name="Profits",
            opacity=0.75
        ))

    if len(losses) > 0:
        fig.add_trace(go.Histogram(
            x=losses,
            nbinsx=bins,
            name="Losses",
            opacity=0.75
        ))

    # --- Layout ---
    fig.update_layout(
        title="Profit & Loss Distribution",
        xaxis_title="P&L per Trade ($)",
        yaxis_title="Number of Trades",
        barmode="overlay",
        template="plotly_white"
    )

    fig.show()

    # --- Optional summary stats ---
    stats = {
        "win_rate": len(profits) / len(trade_list) if trade_list else 0,
        "avg_profit": profits.mean() if len(profits) else 0,
        "avg_loss": losses.mean() if len(losses) else 0,
        "profit_factor": (
            profits.sum() / abs(losses.sum())
            if len(losses) and losses.sum() != 0 else np.inf
        )
    }

    print("\n\nSummary Stats:")
    for k, v in stats.items():
        print(f"{k}: {v}")
    print("---------------------------------")

